import{_ as l,l as o,o as a,c as s,v as i,p as c,x as r,d,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"设备树与 ACPI","description":"","frontmatter":{"title":"设备树与 ACPI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/devicetree-acpi.md","filePath":"cs/devicetree-acpi.md","lastUpdated":1789023840000}'),A={name:"cs/devicetree-acpi.md"};function h(P,e,m,C,_,I){const t=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=i('<h1 id="设备树与-acpi" tabindex="-1">设备树与 ACPI <a class="header-anchor" href="#设备树与-acpi" aria-label="Permalink to &quot;设备树与 ACPI&quot;">​</a></h1><div class="epigraph"><p>设备树用 DTB 描述非发现总线的硬件；ACPI 用表与 AML 在 PC 上描述资源、热插与电源。内核靠它们实例化设备。</p><footer>—— 据 Devicetree 规范；ACPI 规范概述；Linux 对 OF/ACPI 的文档</footer></div><p><a href="/cs/kernel-cmdline">cmdline</a> 不能列出每条 I2C 设备。<a href="/cs/dma-coherence">PCI</a> 可探测。缺口是 <strong>固件描述</strong>：DT vs ACPI，以及两者如何接到驱动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ARM 板无 BIOS 枚举：DT 节点 + compatible 字符串匹配驱动。x86：ACPI 表、_CRS 资源。缺口：overlay DT、ACPI 与 DT 并存（arm64 服务器）；错描述导致驱动不绑。本课不把 AML 写成编译课。</p><p><span class="marginnote">设备树是数据，不是驱动程序。电源域、时钟也在图里。对象是枚举，不是写驱动逻辑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动：解 DTB 或找 RSDP。创建 <code>struct device</code>。对照 <a href="/cs/scsi-stack">SCSI 扫描</a>：可发现 vs 描述。对照 <a href="/cs/skbuff">net_device</a>：网卡 PCI 可发现，板上 PHY 可能在 DT。对照 systemd：用户态 udev 后课用 uevent。</p>',8)),(a(),c(p,null,{default:r(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FW%5B%22DTB%20%E6%88%96%20ACPI%20%E8%A1%A8%22%5D%20--%3E%20CORE%5B%22%E5%86%85%E6%A0%B8%20device%22%5D%0A%20%20CORE%20--%3E%20MATCH%5B%22compatible%20%2F%20IDs%22%5D%0A%20%20MATCH%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%20probe%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DT/ACPI 把「这块板有什么」从内核源码里拆出，使同一镜像可在多板上启动。错误固件是嵌入式第一杀手。不要写成电路图课。与 <a href="/cs/memory-hotplug">热插拔内存</a>：ACPI 通知是来源。</p><p>安全：恶意 ACPI 可在高特权跑 AML——锁定与签名是平台问题。</p><p>实现上：compatible 是字符串列表，驱动匹配最具体的。ACPI AML 可在启动时解释，错误表能让核在早期挂。arm64 服务器常 ACPI+DT 并存，资源以谁为准要查。 读法上只引用<a href="/cs/kernel-cmdline">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>设备树与 ACPI</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OpenFirmware 历史全文。不保证 RISC-V 只有 DT。下一课内核如何把驱动绑到 device：设备模型。</p><p>版本字段会变，课序钉的是机制对象「设备树与 ACPI」，不是某一主线内核的结构体名。 后课默认：硬件由 DT 或 ACPI 描述并实例化。驱动绑定与总线，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DT 描述不可发现的硬件；ACPI 服务 PC 电源与资源。</li><li>compatible/ID 用来匹配驱动。</li><li>设备模型绑定是下一课。</li><li>出处：Devicetree spec；ACPI；Linux driver model。</li></ul>',11))])}const f=l(A,[["render",h]]);export{T as __pageData,f as default};
